(function(){'use strict';
const X=globalThis.AurumExecution,$=x=>document.getElementById(x),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(x,n=2)=>Number.isFinite(x)?x.toLocaleString('zh-CN',{minimumFractionDigits:n,maximumFractionDigits:n}):'—',pct=x=>Number.isFinite(x)?(100*x).toFixed(2)+'%':'—';
let bars=[],provenance={},report=null,statement=null,statementText='';
const message=t=>$('execution-message').textContent=t;
const opts=()=>({capital:Number($('exec-capital').value),feeBps:Number($('exec-fee').value),minFee:Number($('exec-minfee').value),slippageBps:Number($('exec-slip').value),allocation:Number($('exec-weight').value)/100,mode:$('exec-mode').value,limitBps:Number($('exec-limit').value)});
const csv=(rows,empty)=>{if(!rows.length)return '\uFEFF'+empty+'\r\n';const heads=Object.keys(rows[0]),q=x=>'"'+String(x??'').replace(/"/g,'""')+'"';return '\uFEFF'+[heads,...rows.map(r=>heads.map(h=>r[h]))].map(a=>a.map(q).join(',')).join('\r\n');};
function download(name,text,type='text/csv;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function fx(){const v=$('exec-fx').value.trim();if(!v)return null;const n=Number(v);if(!Number.isFinite(n)||n<=0)throw Error('美元折算需要填写正数汇率：1美元折合多少人民币');return n;}
function moneyCards(m){return [['净盈亏 / CNY',fmt(m.netPnl),'现金＋持仓市值−初始本金'],['已实现盈亏 / CNY',fmt(m.realizedPnl),'卖出收入−分摊买入成本−卖出费用'],['未实现盈亏 / CNY',fmt(m.unrealizedPnl),'收盘估值−剩余含费成本'],['最大回撤',pct(m.maxDrawdown),'历史回放；不是实盘账户']].map(([a,b,c])=>`<div class="metric"><small>${a}</small><strong>${b}</strong><p>${c}</p></div>`).join('');}
function rowsHtml(rows,keys){return rows.map(r=>'<tr>'+keys.map(k=>'<td>'+esc(typeof r[k]==='number'?fmt(r[k],['price','reference_price','limit_price'].includes(k)?3:['quantity','filled_qty','cancelled_qty'].includes(k)?0:2):r[k]??'—')+'</td>').join('')+'</tr>').join('');}
function plot(rows){if(!rows.length)return '';const vals=rows.map(x=>x.net_pnl).concat(0),lo=Math.min(...vals),hi=Math.max(...vals),span=hi-lo||1,x=i=>55+i*870/Math.max(1,rows.length-1),y=v=>220-(v-lo)/span*180;return `<svg viewBox="0 0 960 270" role="img" aria-label="人民币净盈亏历史回放"><line x1="55" y1="${y(0)}" x2="925" y2="${y(0)}" stroke="#bbb" stroke-dasharray="4 3"/><polyline points="${rows.map((r,i)=>x(i)+','+y(r.net_pnl)).join(' ')}" fill="none" stroke="#397e78" stroke-width="2.5"/><text x="4" y="30">¥${fmt(hi)}</text><text x="4" y="235">¥${fmt(lo)}</text><text x="55" y="260">${rows[0].date}</text><text x="925" y="260" text-anchor="end">${rows.at(-1).date}</text></svg>`;}
function calculate(){try{const c=opts(),rate=fx();report=X.research(bars,c);const m=report.walk.metrics;
 $('execution-metrics').innerHTML=moneyCards(m);$('execution-chart').innerHTML=plot(report.walk.equity);
 $('execution-summary').textContent=`${bars[c.train||120].date} 至 ${bars.at(-1).date}；${report.walk.equity.length}个交易日，${m.fillCount}笔参考成交，${m.closedTrades}次完成交易，${m.cancelledOrders}张订单有剩余撤销，日终活动订单${m.openOrders}。每次建仓资金比例${c.allocation*100}%；手续费合计¥${fmt(m.fees)}，已在成交价计入的滑点约¥${fmt(m.slippageCost)}。${m.closedTrades<30?'完成交易不足30次（本项目观察门槛），暂不能据此估计稳定胜率。':''}${rate?'按手填汇率1 USD = '+rate+' CNY，净盈亏参考折算$'+fmt(m.netPnl/rate)+'（非历史逐日换汇、非美元账户收益）。':''}`;
 $('execution-compare').innerHTML=[['滚动训练选择',m],['同资金/同仓位买入持有',report.benchmark.metrics],['现金（不计利息）',report.cash.metrics]].map(([name,a])=>`<tr><td>${name}</td><td>${fmt(a.netPnl)}</td><td>${pct(a.totalReturn)}</td><td>${pct(a.maxDrawdown)}</td><td>${fmt(a.fees)}</td><td>${fmt(a.liquidationEstimate)}</td></tr>`).join('');
 $('execution-folds').innerHTML=report.folds.map(f=>`<tr><td>${f.trainStart} / ${f.trainEnd}</td><td>${f.testStart} / ${f.testEnd}</td><td>${esc(X.STRATEGIES.find(s=>s[0]===f.selected)?.[1])}</td><td>${f.candidates.map(a=>esc(a.label)+' '+pct(a.trainReturn)).join(' / ')}</td></tr>`).join('');
 $('execution-orders').innerHTML=rowsHtml(report.walk.orders.slice(-50),['date','order_id','side','order_type','limit_price','requested_qty','filled_qty','cancelled_qty','status','reason'])||'<tr><td colspan="10">无委托。现金也是有效决策。</td></tr>';
 $('execution-fills').innerHTML=rowsHtml(report.walk.fills.slice(-50),['date','side','reference_price','price','quantity','amount','fee','slippage_cost','cash_after','realized_pnl'])||'<tr><td colspan="10">无参考成交，不产生盈利。</td></tr>';
 $('execution-assumptions').textContent=report.method+' '+report.walk.assumptions.join(' ');
 $('execution-stress').innerHTML=[0,5,15,30].map(s=>{const fixed=X.simulate(bars,report.schedule,{...c,slippageBps:s}),refit=X.research(bars,{...c,slippageBps:s});return `<tr><td>${s}</td><td>${fmt(fixed.metrics.netPnl)}</td><td>${fmt(refit.walk.metrics.netPnl)}</td><td>${refit.folds.map(f=>esc(f.selected)).join(' → ')}</td></tr>`;}).join('');
 $('execution-source').textContent=`行情来源：${provenance.source||'未声明'}；价格口径：${provenance.priceBasis||'未声明'}。${provenance.synthetic?'当前为合成样例，金额不是实际业绩。':/前复权|后复权|qfq|hfq/.test(provenance.priceBasis||'')?'当前为复权样本，人民币金额仅作模型演示；实际资金账本应使用未复权价格并处理分红。':'仍须核对实际交易价格与数据口径。'} 当前无券商连接，不能发单或撤真实订单。`;
 message('执行回放计算完成。历史研究与实际成交账本分别显示。');if(statementText)reconcileStatement();
 }catch(e){report=null;message(e.message);$('execution-metrics').innerHTML='';$('execution-chart').innerHTML='';for(const id of ['execution-compare','execution-folds','execution-orders','execution-stress','execution-fills'])$(id).innerHTML='';}}
function reconcileStatement(){try{if(!statementText)throw Error('请先选择成交CSV');const c=opts();statement=X.reconcile(statementText,{capital:c.capital,mark:bars.at(-1).close,markDate:bars.at(-1).date,symbol:bars[0].symbol});$('statement-summary').textContent=`用户声明成交账本（未连接券商核验）：净盈亏¥${fmt(statement.netPnl)}；已实现¥${fmt(statement.realizedPnl)}，未实现¥${fmt(statement.unrealizedPnl)}；现金¥${fmt(statement.cash)}，持仓${statement.quantity}份；估值单价¥${fmt(statement.mark,3)}，估值日${bars.at(-1).date}。${statement.note}`;}catch(e){statement=null;$('statement-summary').textContent=e.message;}}
window.addEventListener('aurum-data',e=>{bars=e.detail.bars;provenance=e.detail.provenance;statement=null;statementText='';$('statement-file').value='';$('statement-summary').textContent='尚未导入真实成交记录。历史行情回测不能记作实盘盈利。';calculate();});
$('execution-run').onclick=calculate;
$('execution-orders-export').onclick=()=>{if(report)download('Aurum_DAY委托_模拟.csv',csv(report.walk.orders,'order_id,date,status,simulation'));};
$('execution-fills-export').onclick=()=>{if(report)download('Aurum_逐笔成交_模拟.csv',csv(report.walk.fills,'trade_id,order_id,date,symbol,side,price,quantity,fee,simulation'));};
$('execution-equity-export').onclick=()=>{if(report)download('Aurum_人民币资金日报_模拟.csv',csv(report.walk.equity,'date,cash,quantity,equity,net_pnl'));};
$('execution-json-export').onclick=()=>{if(report)download('Aurum_执行研究.json',JSON.stringify({...report,provenance,fxReference:fx(),actualStatement:statement},null,2),'application/json');};
$('statement-template').onclick=()=>download('券商已成交记录模板.csv','\uFEFFdate,trade_id,order_id,symbol,side,quantity,price,fee,currency\r\n');
$('statement-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;statementText=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());reconcileStatement();}catch(err){statement=null;statementText='';$('statement-summary').textContent='文件读取失败，请保存为UTF-8 CSV。';}};
$('statement-export').onclick=()=>{if(statement)download('Aurum_用户声明成交对账.csv',csv(statement.rows,'date,trade_id,symbol,quantity,price,fee'));};
})();
